// 1. Odczyt wierszy z Google Sheets
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);

// 2. Odczyt pytania użytkownika z Chat Trigger
const chatNode = $('Chat Trigger').first().json;
const chatInput = String(chatNode.chatInput || chatNode.message || chatNode.text || '').trim();

// 3. Formatowanie danych arkusza w czytelnej strukturze JSON oraz lista kolumn
const sheetData = JSON.stringify(rows, null, 2);
const columnsList = rows.length > 0 ? Object.keys(rows[0]).join(', ') : 'Produkt, Ilosc, Jednostka, Minimum, Kategoria';

// 4. Instrukcja systemowa dla asystenta z obsługą modyfikacji magazynu
const systemPrompt = `Jesteś inteligentnym asystentem domowej spiżarni i magazynu, zintegrowanym z Arkuszem Google.\nTwoim zadaniem jest odpowiadanie na pytania oraz ZARZĄDZANIE STANEM W ARKUSZU (dodawanie produktów, zmiana ilości, zdejmowanie ze stanu).\n\nKOLUMNY W TWOIM ARKUSZU TO: ${columnsList}\n\nTWOJE ZADANIA:\n1. MODYFIKACJA STANU (np. "kupiłem 2 mleka", "zmień ilość jajek na 10", "zdejmij ze stanu mleko", "zużyłem passatę", "dodaj czosnek 3 sztuki"):\n   - Ustaw pole "action": "update".\n   - W polu "reply" napisz zwięzłe, przyjazne potwierdzenie (np. "✅ Zaktualizowałem stan: Mleko ma teraz 4 l" lub "✅ Zdjąłem Mleko ze stanu (ilość: 0 l)" lub "✅ Dodałem Czosnek (3 szt) do spiżarni").\n   - W obiekcie "row" podaj dane wiersza do zapisu/aktualizacji. Użyj DOKŁADNIE takich samych nazw kluczy jak kolumny arkusza:\n     * Nazwa produktu w polu "Produkt" (dla istniejącego produktu użyj DOKŁADNIE takiej nazwy jak w tabeli, np. "Mleko", dla nowego podaj nową nazwę).\n     * "Ilosc": nowa obliczona wartość liczbowa (np. "zdejmij ze stanu" -> 0; "zużyłem passatę" -> 0; "kupiłem 2 mleka" przy obecnych 2 -> 4; "zmień na 5" -> 5).\n     * Pozostałe kolumny (np. Jednostka, Minimum, Kategoria) zachowaj z tabeli, a dla nowo dodanych produktów uzupełnij logicznymi wartościami.\n\n2. PYTANIA I PRZEPISY (np. "chcę zrobić naleśniki, czego brakuje?", "co mogę ugotować?", "czego brakuje w spiżarni?", "ile mamy jajek?"):\n   - Ustaw pole "action": "answer".\n   - Pole "row" ustaw na null.\n   - W polu "reply" udziel wyczerpującej, sformatowanej w Markdown odpowiedzi (użyj wiedzy kulinarnej i dokładnie porównaj potrzebne składniki ze stanem spiżarni w tabeli).\n\n3. TEMATY NIEZWIĄZANE (np. polityka, historia, pogoda):\n   - Ustaw pole "action": "answer", "row": null.\n   - W polu "reply" odmów: "W arkuszu nie ma informacji na ten temat - pomagam wyłącznie w sprawdzaniu i aktualizacji zapasów oraz planowaniu kuchni."\n\nODPOWIADAJ WYŁĄCZNIE W POPRAWNYM FORMACIE JSON:\n{\n  "action": "update" | "answer",\n  "reply": "tekst odpowiedzi lub potwierdzenia dla użytkownika",\n  "row": { "Produkt": "...", "Ilosc": 0, ... } // lub null gdy action=="answer"\n}`;

const userPrompt = `DANE Z ARKUSZA GOOGLE:\n${sheetData}\n\nPOLECENIE / WIADOMOŚĆ UŻYTKOWNIKA:\n${chatInput || '(brak pytania - przedstaw się i napisz w czym możesz pomóc)'}`;

const fullPrompt = `${systemPrompt}\n\n========================================\n${userPrompt}`;

return [{
  json: {
    chatInput,
    rowCount: rows.length,
    payload: {
      contents: [
        {
          parts: [
            { text: fullPrompt }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        responseMimeType: "application/json",
        maxOutputTokens: 8192
      }
    }
  }
}];

// Parsowanie odpowiedzi JSON wygenerowanej przez Gemini
const resp = $input.first().json;
let parsed = null;

try {
  const candidate = resp.candidates && resp.candidates[0];
  if (candidate && candidate.content && candidate.content.parts) {
    const validParts = candidate.content.parts.filter(p => !p.thought);
    const partsToUse = validParts.length > 0 ? validParts : candidate.content.parts;
    const rawText = partsToUse.map(p => p.text || '').join('').trim();
    const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(cleaned);
  } else if (resp.text) {
    parsed = JSON.parse(resp.text);
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      action: 'answer',
      reply: '⚠️ Nie udało się zinterpretować polecenia. Spróbuj zadać je ponownie.'
    }
  }];
}

// Jeśli akcją jest modyfikacja arkusza i mamy wiersz do zapisu
if (parsed.action === 'update' && parsed.row && typeof parsed.row === 'object') {
  return [{
    json: {
      ...parsed.row,
      action: 'update',
      reply: parsed.reply || '✅ Zaktualizowano arkusz.'
    }
  }];
}

// W przeciwnym razie zwykła odpowiedź tekstowa
return [{
  json: {
    action: 'answer',
    reply: parsed.reply || 'Gotowe!'
  }
}];

// Potwierdzenie pomyślnego zapisu w arkuszu
const decision = $('Parsuj decyzję AI').first().json;
const reply = decision.reply || '✅ Pomyślnie zaktualizowano dane w Arkuszu Google!';
return [{ json: { output: reply } }];

// Przekazanie standardowej odpowiedzi czatu
const item = $input.first().json;
const reply = item.reply || 'Gotowe!';
return [{ json: { output: reply } }];
